public class ThreadSafetyExample {
    // 'volatile' guarantees visibility and prevents reordering
    private volatile boolean ready = false;
    private int value = 0;

    public void writer() {
        value = 42; // Happens-before write to 'ready'
        ready = true;
    }

    public void reader() {
        if (ready) { // Happens-after read of 'ready'
            // Guaranteed to see value == 42 due to happens-before
            System.out.println(value);
        }
    }
}
